From a33d542fbd819ca42e4e8d49ed108b179e238276 Mon Sep 17 00:00:00 2001
From: chehefen <chehefen@amazon.com>
Date: Sun, 26 Apr 2020 17:02:52 -0700
Subject: [PATCH] fix bug introduced by 0099c46 that cause master to ignore
 incoming offer in trickle ice mode. In viewer sample, generate random client
 id each time


diff --git a/samples/kvsWebRTCClientViewer.c b/samples/kvsWebRTCClientViewer.c
index d341cac7d9..c3c0c51287 100644
--- a/samples/kvsWebRTCClientViewer.c
+++ b/samples/kvsWebRTCClientViewer.c
@@ -41,7 +41,7 @@ INT32 main(INT32 argc, CHAR *argv[])

     pSampleConfiguration->signalingClientCallbacks.messageReceivedFn = viewerMessageReceived;

-    strcpy(pSampleConfiguration->clientInfo.clientId, SAMPLE_VIEWER_CLIENT_ID);
+    sprintf(pSampleConfiguration->clientInfo.clientId, "%s_%u", SAMPLE_VIEWER_CLIENT_ID, RAND() % UINT32_MAX);

     retStatus = createSignalingClientSync(&pSampleConfiguration->clientInfo, &pSampleConfiguration->channelInfo,
                                           &pSampleConfiguration->signalingClientCallbacks, pSampleConfiguration->pCredentialProvider,
-- 
2.25.1



diff --git a/samples/Common.c b/samples/Common.c
index dd78de257e..f462799197 100644
--- a/samples/Common.c
+++ b/samples/Common.c
@@ -121,19 +121,18 @@ STATUS masterMessageReceived(UINT64 customData, PReceivedSignalingMessage pRecei
     PSampleConfiguration pSampleConfiguration = (PSampleConfiguration) customData;
     PSampleStreamingSession pSampleStreamingSession = NULL;
     UINT32 i;
-    BOOL locked = FALSE, sessionExisted = FALSE;
+    BOOL locked = FALSE;
+    ATOMIC_BOOL expected = FALSE;

     CHK(pSampleConfiguration != NULL, STATUS_NULL_ARG);

     MUTEX_LOCK(pSampleConfiguration->sampleConfigurationObjLock);
     locked = TRUE;
-
     // ice candidate message and offer message can come at any order. Therefore, if we see a new peerId, then create
     // a new SampleStreamingSession, which in turn creates a new peerConnection
     for (i = 0; i < pSampleConfiguration->streamingSessionCount && pSampleStreamingSession == NULL; ++i) {
         if (0 == STRCMP(pReceivedSignalingMessage->signalingMessage.peerClientId, pSampleConfiguration->sampleStreamingSessionList[i]->peerId)) {
             pSampleStreamingSession = pSampleConfiguration->sampleStreamingSessionList[i];
-            sessionExisted = TRUE;
         }
     }

@@ -155,12 +154,13 @@ STATUS masterMessageReceived(UINT64 customData, PReceivedSignalingMessage pRecei

     switch (pReceivedSignalingMessage->signalingMessage.messageType) {
         case SIGNALING_MESSAGE_TYPE_OFFER:
-            if (!sessionExisted) {
+            if (ATOMIC_COMPARE_EXCHANGE_BOOL(&pSampleStreamingSession->sdpOfferAnswerExchanged, &expected, TRUE)) {
                 CHK_STATUS(handleOffer(pSampleConfiguration,
                                        pSampleStreamingSession,
                                        &pReceivedSignalingMessage->signalingMessage));
             } else {
-                DLOGD("session still active, ignore new offer that has the same client id");
+                DLOGD("Offer already received, ignore new offer from client id %s",
+                      pReceivedSignalingMessage->signalingMessage.peerClientId);
             }
             break;
         case SIGNALING_MESSAGE_TYPE_ICE_CANDIDATE:

diff --git a/samples/Samples.h b/samples/Samples.h
index 061dde8b51..63629462c3 100644
--- a/samples/Samples.h
+++ b/samples/Samples.h
@@ -74,6 +74,7 @@ struct __SampleStreamingSession {
     volatile ATOMIC_BOOL terminateFlag;
     volatile ATOMIC_BOOL candidateGatheringDone;
     volatile ATOMIC_BOOL peerIdReceived;
+    volatile ATOMIC_BOOL sdpOfferAnswerExchanged;
     volatile SIZE_T frameIndex;
     PRtcPeerConnection pPeerConnection;
     PRtcRtpTransceiver pVideoRtcRtpTransceiver;

